  const rewriter = new HTMLRewriter().on("script, style, noscript, iframe, object, embed", {
    element() {
      skipContent = true;
    },
    text() {}
  }).on("*", {
    element(element) {
      if (!["script", "style", "noscript", "iframe", "object", "embed"].includes(element.tagName)) {
        skipContent = false;
      }
    },
    text(input) {
      if (!skipContent) {
        text2 += input.text;
      }
    }
  }).transform(new Response(html));
  await rewriter.text();
